def filterOccupiedIntervals(occupiedIntervals, freeStart, freeEnd):
    # Sort by start so overlapping or touching intervals become neighbours
    intervals = sorted(occupiedIntervals)

    # Merge intervals that overlap or touch (next start <= previous end + 1)
    merged = []
    for start, end in intervals:
        if merged and start <= merged[-1][1] + 1:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])

    # Remove the free interval from every merged interval
    result = []
    for start, end in merged:
        # Part strictly to the left of the free interval
        left_end = min(end, freeStart - 1)
        if start <= left_end:
            result.append([start, left_end])
        # Part strictly to the right of the free interval
        right_start = max(start, freeEnd + 1)
        if right_start <= end:
            result.append([right_start, end])
    return result
